window.DIWAN_INDEX=[{"t": "من تعب يبغي العلا ماتندم في الأخير", "s": "قصائد النصح", "u": "poems/001.html", "x": "من تعب يبغي العلا ماتندم في الأخير | والمراجل كايده مايحصلها كسول | الرجل تعرف مباديه من عاده صغير | يعرفونه من مباديه صاحين العقول | من تهاون يبغي يجيد لا قد هو كبير | يمكن إنه مايجي له مع العالم قبول | العمر محدود والموت مامنه نذير | والزمن دوار ما يامنه كون مهبول | ورزقنا عند الولي ربنا العالي القدير | غير كل إنسان حرص على رزقه عجول | بنصحك ياغافل القلب حقق بالمسير | وإجتهد في الدين وإتبع إرشادات الرسول | من يطيع الله لو هو عمى يحسب بصير | يطلب الله يخرجه من خطر يوم يهول | أذكر الله عد وبلن هطل سيله غزير | والسموحه كان في محتوى قولي ميول"}, {"t": "خلوني أسير دام الرجل تمشي بي", "s": "قصائد النصح", "u": "poems/002.html", "x": "خلوني أسير دام الرجل تمشي بي | ومادام عيني على الممشى تقديها | مافات لي من سنه زادت بي الشيبي | وأيامي اللي مضت كثرت لياليها | إن طال عمري تبين في عذاريبي | بيجيني نقوص مالي حيلةٍ فيها | أهز نفسي على الفزعات وأهيبي | وبعض المشاوير أهم بها واخليها | أذل منها ولا ابغي الناس تدريبي | مابغي العرب تدري إني عاجز فيها | ليت السنافي يسمكر وله توضيبي | نحط عمره ثلاثين وحواليها | من دون ماخص بابدي هل الطيبي | اللي هدفهم على العليا ومافيها | بدفع عليهم فلوسٍ لو فضى جيبي | أعمار الأبطال غالي المال يفديها | يستاهل المدح ذابح شمخ النيبي | اللي ضيوفه الى جاته يعشيها | يوم العسر مايصد من المواجيبي | يمناه في مده الجوده مضريها | يستاهل اللي حمى حرش العراقيبي | لأختفت القوم حول عند تاليها | من ثقل قلبه ماهو يخطي المضاريبي | له عزوه من سمعها يعترف فيها | يستاهل اللي الى جات المطاليبي | كبود ربعه من الطنيه يداويها | من دون ربعه يوقف وقفه الذيبي | كبود يشفع لها و كبود يكويها | يستاهل اللي جريٍن ماهو يهيبي | رجله على مصلحه ربعه معنيها | عزام بالطيب ماطاع الزواريبي | والهرجه الضايعه مايلتفت فيها"}, {"t": "الزمن يعطي دروس يشيب بها الرضيع", "s": "قصائد النصح", "u": "poems/003.html", "x": "الزمن يعطي دروس يشيب بها الرضيع | والعرب في غفلةٍ ماتقوم رقودها | النصايح كان تشرى وصارت دون بيع | وشفتها في تالي الوقت وقف فودها | الصقر ماعاد يقدر يعدل اللي يضيع | خايف من هرجةٍ ضايعٍ مردودها | مكسبك في مسكت الدين والصدر الوسيع | وعذلان النفس وإقناعها من زودها | أترك الحاقد وحاول على الرأي الرفيع | حط عقال العرب في نحر مقرودها"}, {"t": "من تعدا نقطة الحق يتبع له شهير", "s": "قصائد النصح", "u": "poems/004.html", "x": "من تعدا نقطة الحق يتبع له شهير | ضايع وغادي وحضه ردي والله بلاه | لو يقول إني كبير يقال إنك صغير | جاهل ماهو يميز صديقه من عداه | تاركٍ درب السنع راكبٍ دربٍ مرير | ياخساره ضمة اللي مثل ذا و أشبهاه | في المجالس ماهو يفز لجاه الكبير | يفهق أرجيله وهو مادرى مالي وطاه | قاعدن في زاويه منعطف كنه كسير | بس يضحك من صور هاتفه ومن زملاه | يحسبنه رجل كامل وهو كنه غرير | صرفته في روحه أكبر دليل في خطاه | مافعل مشهوره يجيك كنه مستذير | طايرٍ شبحه ويهرج ويخطي في حكاه | يتبع الشله ويترك هله كنه أسير | ويجحد علومه ع أهله ويبدي لاخوياه"}, {"t": "ترى الأبن عم اللي لاجاء لزومك فيه", "s": "قصائد النصح", "u": "poems/005.html", "x": "ترى الأبن عم اللي لاجاء لزومك فيه | رفض ماتقدم في لزومك وهو قادر | إلا جاك ماهو لازم إنك تستر فيه | قله عندنا وإلا رفض خله يغادر | إذا جاه مشكلة من الله لا تبكيه | لايبكي عيونك واحد ماهوب نادر | خل بكاك للي لأعترض للعرب طاريه | قالوا كلهم نعمٍ على فعله البادر | صبي الصمايل يجرح الجرح ويداويه | يعرف الكلام الوارد ويعرف الصادر"}, {"t": "البارحه عيني تشوف ولا أدري ويشي تشوف", "s": "قصائد النصح", "u": "poems/006.html", "x": "البارحه عيني تشوف ولا أدري ويشي تشوف | تشوف شي مايونسي ضامري و ألدها | أشوف شي محدثٍ من قبل ماهو بمعروف | شيءٍ يتك الصدر منه النفس وصلت حدها | أشوف جيلٍ يتبع الموضات من كل الصنوف | حريم ورجالٍ مع الجهال لو بتعدها | تخسر على شي ماله داعي ولاهو بمخلوف | وتهوم هوماتٍ خياليات ماهي قدها | وقام الرجل يهرج بهرجٍ كذب ويخلى يطوف | ماعاد به رجلٍ يعارض كذبته ويردها"}, {"t": "قد راعي الهرج الصحيح يكنسله لأنه يخوف", "s": "قصائد النصح", "u": "sections/nasaeh.html#p7", "x": "قد راعي الهرج الصحيح يكنسله لأنه يخوف | من واحدٍ عنده يحرف السالفه ويمدها | الخير واجد غير انا من ذا البشر نفسي عيوف | لا عافت العربان خل النفس تتبع ودها | صحيح ماهو يتفق في الرأي كون أهل الشفوف | اللي هدفهم فالمراجل مالرخوم تحدها"}, {"t": "السنه إهي السنه والشهور إهي الشهور", "s": "قصائد النصح", "u": "poems/008.html", "x": "السنه إهي السنه والشهور إهي الشهور | بس خلق الله والوقت جاء فيه إختلاف | وصارت الدنيا وشغلاتها لعبة بزور | وبعض خلق الله من الدين جاء فيه إنحراف | قامت العالم تمارى بتصليح القصور | والمراعي سكرت والخطاء ماهو يشاف | وراعي الأبل لا بغى العشب ماعين عبور | كون مع شبك يحده ومع طرق كساف | وين راعي الذمة اللي على الديرة غيور | يصل العلم المفصل ولا قلبه يخاف | يصل العلم الحكومة مقصرت الشبور | اللي ثقال العرب عندها تاتي خفاف"}, {"t": "ياسعود عندي لك بيوت جديدات", "s": "قصائد النصح", "u": "poems/009.html", "x": "ياسعود عندي لك بيوت جديدات | ركز عليها ثم عطنا بدلها | رجل في ذا الدنيا بليا طموحات | تصعب عليه الكايده مانقلها | حنا نبي الراحه والأيام عجلات | الله يكفي شرها ماأعجلها | دنيا تبي منا على كل الأوقات | في الدين والدنيا نزاول عملها | نبي نتجمل مع رجال الجمالات | الطيب قمه ناجح من نزلها | ترا الردي لو مات ذكره معه مات | ولا المراجل باقي ذكر اهلها"}, {"t": "النوم ماهو يجيب المال", "s": "قصائد النصح", "u": "poems/010.html", "x": "النوم ماهو يجيب المال | مايكسب المال كسلاني | المال يبغي شطير عيال | على العمل غير متواني | يعمل مع الصاحي العقال | قد جرب المر والحالي | يعرف خراجه من المدخال | ولا وهقه كل حيالي | حيال صرفه ولا ينحال | وبالمرجلة موقفه عالي | منزله ياتي عليه اقبال | ويقدرونه وهو غالي"}, {"t": "البخيل الي لا منك نفعته ماشكر", "s": "قصائد النصح", "u": "poems/011.html", "x": "البخيل الي لا منك نفعته ماشكر | والجمايل فيك يصعب عليه يعدها | ناكر المعروف لاجاء مجالك ماذكر | والمدايح فيك يشفق على إنه يصدها | إن حضر في المجتمع بالسواليف إشتهر | يهرج هروج كثيره ولاهو قدها | قال بعض الي حضر ليت هاذا ماحضر | لجت(ن) ماينعرف كذبها من جدها"}, {"t": "أصارع الدنيا واجامل مع الناس", "s": "قصائد النصح", "u": "poems/012.html", "x": "أصارع الدنيا واجامل مع الناس | وأذخر رفيقي لو غدى فيه ميله | وأخذ مع درب المطاليق مرواس | ولا المراجل نوب تاتي ثقيله | مايكسب الطاله ولا ياخذ الكأس | رجل يطاوع للعلوم الهزيله | بعض البشر لاجاك للنبض جساس | يحط مشخاطه وزان الفتيله | كنه صديق وهو خسيس وبلاس | ينقل حكي بين العميل وعميله | لا ولعت ضوك على ذا البشر داس | يجيب لك هرج قليل ذبيله | من يوم خلق الكون والعالم أجناس | وكلن على ماقيل فكره دليله"}, {"t": "طب المقفي لا ترده تراضيه", "s": "قصائد النصح", "u": "sections/nasaeh.html#p13", "x": "طب المقفي لا ترده تراضيه | خله على وجهه يعالج خطاياه | إن جاء يدير رضاك فالله يحيه | وإن صد منك هفة مقيط ورشاه | لاصار داري بالخطاء كيف ترضيه | متعمدٍ أخطاه يمشي بعمياه"}, {"t": "رفيقك اللي زايده مايزودك", "s": "قصائد النصح", "u": "poems/014.html", "x": "رفيقك اللي زايده مايزودك | مايلزمك تعطيه لو جاك زايد | عنده سوا غيبتك ولا وجودك | مجاملك له دوم ماهوب فايد | لاصار ماهو واحد من عضودك | يشيل ذروا الحمل لاصار كايد | أحلم عليه ولا تبيح سدودك | للناس تفرح بك خبول البدايد | خله على فاله وجود حدودك | يعطيه درس الوقت ويجيك عايد"}, {"t": "ابتدي باسم الله الوالي القدير", "s": "قصائد النصح", "u": "poems/015.html", "x": "ابتدي باسم الله الوالي القدير | ربنا اللي كلنا نرجي عطاه | الله اللي من عذابه نستجير | نطلبه عفوه وحنا في رجاه | عقب ذكره ببدع القاف اليسير | دام بدع القاف بيزين معناه | يارجال تستمتع هرج الشوير | وضعكم مخطور من كل إتجاه | وضعكم ذا فيه شر وفيه خير | خلوا الغفله وشدوا الإنتباه | ماتساوى سير الاعمى والبصير | والسعد تلقاه في حب الصلاه | يا أُمة محمد على الدرب المنير | حثوا الممشى بتغيير الحياه | مالنا في سنة محمد خشير | ومن تركها ف إحسبونا من عداه | وقفوا بالشر في وجه الشرير | لين يترك دربه ويعرف خطاه"}, {"t": "ترا صبي مابه همه", "s": "قصائد النصح", "u": "poems/016.html", "x": "ترا صبي مابه همه | لاشاف الريبه يرتابي | يقال الله خله لأمه | ولا يحسب له حسابي | ماهو يذكر وسط القمه | ولا يفقد لا من غابي | ترى النادر يرد الجمه | إلا هابوا الهيابي | يرفع من ذراعه كمه | ويترجز بالهندابي | حماسه يمشي في دمه | إن هاب الهايب ماهابي"}, {"t": "إلا ذكرت اللي مضى قلت حيه", "s": "قصائد النصح", "u": "poems/017.html", "x": "إلا ذكرت اللي مضى قلت حيه | تبكي عيوني ذكر وقت لنا فات | يومٍ مجالسنا لها قابليه | فيها رجالٍ يحفظون الروايات | إلا هرج راعي العلوم الطريه | نصمت ونكمل تالي الصمت بسكات | يروي لنا مواقف أهل الحميه | ماهو كلام هياط كذب وخرافات"}, {"t": "فالمواقف لا تمالي هل الرأي الهزيل", "s": "قصائد النصح", "u": "poems/018.html", "x": "فالمواقف لا تمالي هل الرأي الهزيل | العزوم الزايده للحمول الكايده | كم شوير يمنع الرأي ماعنده بديل | قال منهو يعرفه أي ذي عوايده | إن عطاك الرأي ماشفت لك منه حصيل | يشغلك ب أشوار مالك وراها فايده | السنافي فيه عزم على للحمل الثقيل | قو عزمه يجبره للحمول الكايده"}, {"t": "ترا الردي جيده حلول الفراغات", "s": "قصائد النصح", "u": "poems/019.html", "x": "ترا الردي جيده حلول الفراغات | ويعجبك هرجه في حلول العوافي | ويقل هرجه في وقوت المهمات | وإن جاء اللزوم العسر ماهو يشافي | يكفيه قرمٍ مايحب الدعايات | ولا ينتظر لا قيل وين السنافي | يأمر على روحه على الشغل بسكات | لو هو بشغل حط ذا الشغل إضافي"}, {"t": "يا أهل العقول السليمه", "s": "قصائد النصح", "u": "poems/020.html", "x": "يا أهل العقول السليمه | للشر شفنا علامه | ماعاد في الناس شيمه | والدين قل إحترامه | وقع على السيل ديمه | والوقت حلل حرامه | من جاء إبن عمه خصيمه | ماعاد يلقى مرامه | الوقت يبغي عزيمه | والشمل يبغي زعامه | زعامةٍ مستديمه | ماهي زعامة رخامه | تبغي رجال فهيمه | تمشي بعقل وشهامه | ويجي مهم زود قيمه | ويستاهلون الزعامه"}, {"t": "البارحه ماطبق الطرف بنعاس", "s": "قصائد النصح", "u": "poems/021.html", "x": "البارحه ماطبق الطرف بنعاس | يوم كلن مهتني في منامه | وسط الفراش وكن ماعندي أوناس | متكدر بين الحزن والندامه | أشوف وقت غادي في عوكاس | نجني حرار ويطلع الفرخ هامه | ياعيال ياللي عينكم صوب الأدناس | روحوا ولا تقولون مع السلامه | عزاه ياضمٍ وتاليه الإفلاس | ضمة صبي ما براسه شهامه | لا خاف من ربه ولا من حكى الناس | يفضح نباء ربعه وهان الكرامه | بعض العيال دعايته ترفع الراس | فعل الشرف والعز جود زمامه | الدين والدنيا بها ياخذ الكأس | الله يوفقه السعد والسلامه"}, {"t": "الزمن دوار لا أحدٍ يقول إني غني", "s": "قصائد النصح", "u": "poems/022.html", "x": "الزمن دوار لا أحدٍ يقول إني غني | يذكر الرجال ربعه ولو عنده رصيد | ما أمحق من اللي يتردى وعقبه ينثني | يبغي يصلح ف ماله ويبدأ من جديد | من تعب يبغي العلا لو خسر مايحزني | يضرب الكايد ورزقه على رب العبيد | كل شي له جني والفعول لها جني | جنيها يثنى على الرجل بالفعل الحميد | ما أحدٍ يلقى طموحاته اللي يمتني | كون هو قد حد نفسه على الدرب المكيد"}, {"t": "ياعيال غير الدين مابه طماعه", "s": "قصائد النصح", "u": "poems/023.html", "x": "ياعيال غير الدين مابه طماعه | تمسكوا في دينكم يامطاليق | بضاعة يا طيبها من بضاعه | الرابح اللي شدها بالمواثيق | دام السعد للرجل يكفخ شراعه | يطلب ولي الخلق له بالتوافيق | المال للطيب يقوي إندفاعه | على دروب المرجله ماهو يضيق"}, {"t": "أنا أشوف وقت فيه بعض العرب مغرور", "s": "قصائد النصح", "u": "poems/024.html", "x": "أنا أشوف وقت فيه بعض العرب مغرور | ويهرج بهرج مايحسب عواقيبه | لو إنه يعرف العلم ولا يطيع الشور | ترك ذا الكلام اللي لسانه يهذري به | إلا صار ماهو في كلام الغلط مجبور | لا يأمن لسانه لا هذر به يولي به | إحنا في بلادٍ جعل يبطي وهو مسرور | بلاد الرجال اللي لهم في الدول هيبه"}, {"t": "أنا صريح ومن نشدني نصحته", "s": "قصائد النصح", "u": "poems/025.html", "x": "أنا صريح ومن نشدني نصحته | على الطريق اللي يوديه للصح | ولا يحسبني بالنصيحه جرحته | كم واحد عطيته الراي وأفلح | نصيحتي من فضل مولاي بحته | نصيحةٍ لله ما أنا أتمدح | اللي بصدري للنشاما شرحته | ولا أحدٍ يقول محمدٍ بالنصح شح | بعض الكلام إلى هِرج ماسمحته | خص الكلام الي يجنب عن الصح"}, {"t": "اللي يحدك على الممنوع", "s": "نصائح قصيره", "u": "sections/qasira.html#p26", "x": "اللي يحدك على الممنوع | النفس عن جيه إمنعها | ماحلل الحرم كون الجوع | والعالم الله مشبعها | خل الخطأ وأتبع المشروع | محجة محمد إتبعها"}, {"t": "لاجاك من هو حده الوقت ناصيك", "s": "نصائح قصيره", "u": "sections/qasira.html#p27", "x": "لاجاك من هو حده الوقت ناصيك | يبغيك تنسف منه كربه همومه | لا تعتذر من حاجته والله معطيك | لا تشغله وتحط عنده خصومه | ماراح صوبك كون هو هاقي فيك | إنه إلا من جاك تقضي لزومه"}, {"t": "الله يجير المستجير من الجري على الخطير", "s": "نصائح قصيره", "u": "sections/qasira.html#p28", "x": "الله يجير المستجير من الجري على الخطير | لأن الجري على الخطر نفسه رقص شيطانها | شيطانها يامر لها بالسوء والعيش المرير | مايفهم الصالح من الصحبان من عدوانها | يروح في درب الخطأ ماهو يطيع اللي يشير | ناس فلت تمشي كذا ماطاوعت شيبانها"}, {"t": "الرفيق اللي على لابته سيف حديد", "s": "نصائح قصيره", "u": "sections/qasira.html#p29", "x": "الرفيق اللي على لابته سيف حديد | وعند قيمان العرب رفقته مثل العسل | ينقل الأخبار بين العرب مثل البريد | ينقل السيئه ولا ينطق الهرج الجزل | رفقته ماتنشرى ودك إن داره بعيد | واقع في مشكله من غرور الى جهل"}, {"t": "إلا تردى الردي زودت جيدي وراه", "s": "نصائح قصيره", "u": "sections/qasira.html#p30", "x": "إلا تردى الردي زودت جيدي وراه | أخاف نفسي أعوان الهون تدني بها | الهون هين عسى المعبود يقلع مداه | وصعب على تنومس لا ذكر طيبها | الى تردى الردي وأفلس ولا الله عطاه | وقروم الأجواد ماكمل مواجيبها"}, {"t": "ترا الشرير اللي يدور على الشر", "s": "نصائح قصيره", "u": "sections/qasira.html#p31", "x": "ترا الشرير اللي يدور على الشر | يلقى شرير مثل شره ويبلاه | لا صار شري وأقشر يحصل أقشر | يرد دوار القشر من نواياه | اللي مايفزع ل أبن عمه إلا إنضر | حل الفراغه لا يكثر حكاياه"}, {"t": "ترا الطمع تاتي سبوره شياطين", "s": "نصائح قصيره", "u": "sections/qasira.html#p32", "x": "ترا الطمع تاتي سبوره شياطين | تسعى بشي لإختلافات الجماعات | تذكر لك السلبي وتكتم على الزين | وتحط عقال العرب في متاهات | وتحط إشاره واضحه بين قوسين | يفهم عليها اللي يعرف الحواصات"}, {"t": "ترا ضيقه الخاطر تخلي الرجال تضيع", "s": "نصائح قصيره", "u": "sections/qasira.html#p33", "x": "ترا ضيقه الخاطر تخلي الرجال تضيع | تخلي كثير العرف يخطي التصرافي | ترا ضيقي بابيعها في مزاد البيع | وبامشي مع اللي ناويين بالنكافي"}, {"t": "من كان عزمه ردي مايقدر يفيدك", "s": "نصائح قصيره", "u": "sections/qasira.html#p34", "x": "من كان عزمه ردي مايقدر يفيدك | يبرد حديده إلا جات المواجيبي | إن كان ماحطمك ماودك يزيدك | ووده يدور على النشمي عذاريبي"}, {"t": "المراجل خلها بين طيب وصدقه", "s": "نصائح قصيره", "u": "sections/qasira.html#p35", "x": "المراجل خلها بين طيب وصدقه | واشتغل لله وما راح لاتحزن عليه | الرياء لاحطه الرجل في الطيب محقه | من غدا طيبه رياء ما العرب تشفق عليه"}, {"t": "المراجل كايده غير تاتي هينه", "s": "نصائح قصيره", "u": "sections/qasira.html#p36", "x": "المراجل كايده غير تاتي هينه | للصبي اللي على المرجله قلبه عزوم | اللي إلا جاه راعي لزوم عينه | ويتحمل للحمول الثقيلات ويقوم"}, {"t": "ترا الدرب لا من طال مايقطعه كسلان", "s": "نصائح قصيره", "u": "sections/qasira.html#p37", "x": "ترا الدرب لا من طال مايقطعه كسلان | ولا يقطعه صبيٍ بعد بارد جوفه | يبي له صبيٍ في السفر صاحي وفنان | مرحوله على الدرب السنع دايم يحوفه | إلا من زهمته يعتزي كن فيه جنان | يقضي لزومك قبل ويخلي ظروفه"}, {"t": "يالله دخيلك غدا في الناس شئ غريب", "s": "نصائح قصيره", "u": "sections/qasira.html#p38", "x": "يالله دخيلك غدا في الناس شئ غريب | جهالها ماتسمع هرج عقالها | ماكل منهو هرج يهرج بهرج مصيب | لونهم ساكتين السكته أشلى لها | هرج يروج بدون إسناد علم قضيب | كثير منها مايعرف وين قوالها"}, {"t": "من تردى في رفيقه الا جاء له لزوم", "s": "نصائح قصيره", "u": "sections/qasira.html#p39", "x": "من تردى في رفيقه الا جاء له لزوم | يمسك لسانه من المدح وسط المجتمع | اي بعض اهل المناصب من النفع محروم | يمتدح وسط المجالس وهو يخطي السنع"}, {"t": "خوي الفراغه مايفيدك الا جاء الضيق", "s": "نصائح قصيره", "u": "sections/qasira.html#p40", "x": "خوي الفراغه مايفيدك الا جاء الضيق | يخلي خويه جعلها تقصر شبوحه | اللي مايطيع الشور خله الين يفيق | يعطيه اازمان دروس ويعود بروحه | من لا طاع عاقل يخطر بقلة التوفيق | يكلب عليه الوقت وتوقف مزوحه"}, {"t": "طب المقفي لاترده تراضيه", "s": "نصائح قصيره", "u": "sections/qasira.html#p41", "x": "طب المقفي لاترده تراضيه | خله على وجهه يعالج خطاياه | ان جاء يدير رضاك فالله يحيه | وان صد منك هفة مقيط ورشاه | لاصار داري بالخطاء كيف ترضيه | متعمدن اخطاه يمشي بعمياه"}, {"t": "الدنيا ماهي تبقى لحد والعمار قصار", "s": "نصائح قصيره", "u": "sections/qasira.html#p42", "x": "الدنيا ماهي تبقى لحد والعمار قصار | ترا الرابح اللي سالم ن الطمع فيها | كم من واحدن قد شلته ماعطته انذار | وهو ماعطى اللي يطلبه ممل فيها | أنا احب من هو رفقته ماعليها غبار | الا صار عندي غلطتن مايخفيها"}, {"t": "الا شفت رجلن ضايع ورايه مكفيه", "s": "نصائح قصيره", "u": "sections/qasira.html#p43", "x": "الا شفت رجلن ضايع ورايه مكفيه | قصرت النصيحه منه واخوف ينقدني | يروح على رايه وبد الزمن يرضيه | الا من تراجع من خطاياه ييدني"}, {"t": "الا جيت باجازي الردي بالردا مأحتال", "s": "نصائح قصيره", "u": "sections/qasira.html#p44", "x": "الا جيت باجازي الردي بالردا مأحتال | تكدر علي جوي ولا هو يتهيالي | تذكرت هرج الناس من بين قيل وقال | الا قال خاطي قرم والله ماقالي | يدافع على عرضي مع جملة العقال | ولا هو يجامل في مجاراة جهالي"}, {"t": "ترا المراجل ماهي بهرج وضحوك", "s": "نصائح قصيره", "u": "sections/qasira.html#p45", "x": "ترا المراجل ماهي بهرج وضحوك | فيها تعب فيها عزوم وخساره | كنك ترحب بالنشاما الا جوك | يفرح بك الهاشل ويلقى وقاره"}, {"t": "التسرع في القرارات يغوي صاحبه", "s": "نصائح قصيره", "u": "sections/qasira.html#p46", "x": "التسرع في القرارات يغوي صاحبه | التزم في اللي يجملك عند الطيبين | اركب الدرب الذي كل قرم راكبه | لا تجنب عن طريقه يسار ولا يمين"}, {"t": "الكبير يضيق لا من جلس عند الشباب", "s": "نصائح قصيره", "u": "sections/qasira.html#p47", "x": "الكبير يضيق لا من جلس عند الشباب | هرجهم معطي طريق وهو معطي طريق | وإن نشد من ماضي الوقت ماعين جواب | وإن سأل ماجاوبوا له يحس انه يضيق | هرجهم واجد ولاكن ياقل الصواب | والكبير لزايد الهرج ماعاده يليق"}, {"t": "من عقب ماحن كان نعزم ونعزم", "s": "نصائح قصيره", "u": "poems/048.html", "x": "من عقب ماحن كان نعزم ونعزم | لاحن نعزم ولا نحب العزيمه | الله يستر يالنشاما من الذم | الذم عاقبته علينا وخيمه | عينت ناس كن ماهيب تفهم | لما جهل ولا عقول سقيمه | نحلف لهم بالله والدين الأعظم | وأعطيه صدق وصرت كني خصيمه"}, {"t": "لو بغيت الناس تمدحك فحرص لاتضيع", "s": "نصائح قصيره", "u": "sections/qasira.html#p49", "x": "لو بغيت الناس تمدحك فحرص لاتضيع | لاتخاوي واحد ضايع ويضيعك | لو بغاك الضايع ترافقه قل له ماستطيع | باتنحر لازمي وانت روح لسنعك"}, {"t": "ترا النيه مطيه وإفعلوا بالخير يالأجواد", "s": "نصائح قصيره", "u": "sections/qasira.html#p50", "x": "ترا النيه مطيه وإفعلوا بالخير يالأجواد | ومنهو يفعل المعروف يدعى له بالإحساني | ترى راعي الرياء م الناس تشكر سعيه إليا جاد | ولامنه خسر ماله تقول الناس غلطاني"}, {"t": "من كان يطمح للمراجل وصلها", "s": "نصائح قصيره", "u": "sections/qasira.html#p51", "x": "من كان يطمح للمراجل وصلها | يتعب عليها لين يلقى جزاها | ترى المراجل مفلحين أهلها | اهل المراجل عالي مستواها"}, {"t": "اللي قنى الابل ولا هو يعتني فيها", "s": "قصائد الإبل", "u": "poems/052.html", "x": "اللي قنى الابل ولا هو يعتني فيها | احسن له يبيعها ويريح البالي | من كان يحسب حساب اللي يعشيها | ماهوب صابر الى وقت الدهر طالي | ياما على قاصر الأسره مبديها | نصبر على الدين لجل العرب الأجهالي | الأبل كرمها يبيض وجه راعيها | وتسكت اللي يلفق بعض الأقوالي | الأبل تجمل يكون يشح راعيها | فيها اللحم واللبن لجاك هشالي | يعل رجلن يسرحها ويرعيها | مايكرم الضيف منه الخير ينجالي | نفسي من قصورها ماني مزكيها | أرجي المغفره من اللي يرحم الحالي"}, {"t": "اللبل تبي رجل قوي صبر وعزوم", "s": "قصائد الإبل", "u": "poems/053.html", "x": "اللبل تبي رجل قوي صبر وعزوم | عنده على كثر الشدايد عنادي | الا لحقها نقص تلقاه مهموم | في المجتمع تلقاه ماهوب عادي | ومن قال علمك قال ماعندي علوم | انا بوادي وانت تمشي بوادي | ماني على كثر السواليف ملزوم | حاديني من هل السواليف حادي | راعي الابل الا اهمل بها يلحقه لوم | ومخطور من بعض العرب بالسوادي | ياللي تحب البل ترا عندي علوم | علوم تخطر بين مخطي وقادي | العلم جاء به فرق بين امس واليوم | البل بضاعه لاجفاك البلادي | بضاعة اسعارها قبل بسهوم | يوم القبايل بين منكف وعادي | البل بضاعه ضمها كل شغموم | ذخيرتن فيها شراب وزادي | ترحل عليها البدو وتشل وتشوم | وتصبر على حر التعب والبرادي | واليوم في ذا الامن ياعله يدوم | بقيادة اللي جعل رايه سدادي | ابو فهد جعله من الشر معصوم | ياعل يفدونه قلال الرشادي | وعضوده اللي تنقل الحمل وتقوم | مثل البليهي يوم شال العتادي | في مصلحتنا م اهتنت لذة النوم | ثروة وطن من بين حضر وبوادي"}, {"t": "كل ماهوجست في البيع جاني سايبه", "s": "قصائد الإبل", "u": "poems/054.html", "x": "كل ماهوجست في البيع جاني سايبه | انتحت بي وابعد الفكر معها مادريت | وقلبي اللي قاربات على حضايبه | يمكن لحدن يقول انت غلطان بكيت | كل مافكرت في خيره اللبل غايبه | قمت احاول في التنسي ولكن مانسيت | ونفسي اللي مع جميع النصايح تايبه | كم نصيح قد نصحني ومن شوره عصيت | ماكتب لي عند مولاي صوبي جايبه | مايجيب الرزق لك قول حي وقول ليت | شفت ناس تشرب الماء والأخرى هايبه | حالفن اشرب مع الناس ولا ماغزيت | الرجل لعاد ماهو يعرف النايبه | احسن انه مايسوي مع البدوان بيت"}, {"t": "حب البكار السود ماهو يشله", "s": "قصائد الإبل", "u": "poems/055.html", "x": "حب البكار السود ماهو يشله | الا فلوس تتعب اللي يعدون | ولا لزومن كايدن صعب حله | ولا سجين رقاب ولا هل ديون | الأبل وناسة روح ماهي ممله | بعض العرب من ضمة الأبل يعجزون | حبي لها قد هو بقلبي جبله | ماسج من ذودي مع اللي يسجون"}, {"t": "أظروفي من الشده مع مقدم البدوان", "s": "قصائد الإبل", "u": "poems/056.html", "x": "أظروفي من الشده مع مقدم البدوان | حدتني وانا يالربع ماني بغاويها | أدل المراتع كلها وأبخس القيعان | ورجلي على كثر المماشي مضريها | إلا قمت من قال أنت مخطي فهو غلطان | وأنا في ضميري عبرة غير مخفيها | عضيدي وراعي اللبل غدى كنه البزران | وأنا خابره وقت الصعوبات راعيها | يسري بها في الليل إلى ناموا الرعيان | ويصبح وهو بعض المسافات طاويها"}, {"t": "ياهل البل نحمد الله وسعها الولي", "s": "قصائد الإبل", "u": "poems/057.html", "x": "ياهل البل نحمد الله وسعها الولي | وسع الدبره برجعن يونس من مشاه | يحي النبات اللي من الضما عوده بلي | زاين لونه ضحى اليوم يوم الله عطاه | يفرح اللي من مسير البراري ماسلي | وده بذوده ويمشي بذوده في هواه | من يلوم اهل الابل بحبها قلبه خلي | احسن انه مايبين على العالم حكاه"}, {"t": "اللبل اذا ضاقت تضايقت منها", "s": "قصائد الإبل", "u": "sections/ibil.html#p58", "x": "اللبل اذا ضاقت تضايقت منها | مادامها رتاع يرتاح بالي | اللبل لها شومات تبغي وطنها | الى نوت لديارها ماتمالي | يامهبل اللي يوم شامت ومنها | مايامن الابل كون رث العيالي"}, {"t": "أنا سعودي والسعوديه أمي", "s": "وطنيات", "u": "poems/059.html", "x": "أنا سعودي والسعوديه أمي | أكلي ومشروبي عطى من حصيلها | أمي علي أغلى من الناس كلها | تضمني وتعيشني من صميلها | ياحيسفا ياكل رجل سعودي | لا راح من داره نسى من جميلها | دار المعزه ديرة إخوان نوره | ماغيرها لي ديرة أنتمي لها | من يوم عشنا في مراتع وطنها | جعل الحيا في كل موسم يجي لها"}, {"t": "دام الحكم معتز فحنا طيبين", "s": "وطنيات", "u": "sections/wataniyat.html#p60", "x": "دام الحكم معتز فحنا طيبين | الله يعز الدوله بحكامها | في ظل سلمان الحزم ذرب اليمين | وولي عهده رفرفت بأعلامها | المملكه تسعى لخير المسلمين | وتضرب بحد السيف لجل أخصامها"}, {"t": "رؤية 2030", "s": "وطنيات", "u": "sections/wataniyat.html#p61", "x": "جعل صبي رؤيته غيرت ممشى البلاد | ياخذ سنين طويله وهو يرقى سنود | فيه حكمة راي وعناد للراي السداد | خلت بلاده تجي عود في عين الحسود | طلعته مطلاع حر ينومس بالهداد | جعل يبطي حي ويعيش لين يصير عود"}, {"t": "عسى من سعى في خونة المملكه ينصاد", "s": "وطنيات", "u": "poems/062.html", "x": "عسى من سعى في خونة المملكه ينصاد | يصيدونه اللي وظِّفوا في البلد لأجله | إلى قص رأس اللي يخون البلد وش عاد | إلى خذ جزاه من الخطاء وإنطوى سجله | عدو البلاد الى عبث ودك أنْه يباد | تجيه الأوامر لأجل مسكه وهي عجله | وردي المذاهب لا قعد عندنا مافاد | وإلى راح منا خايب وهرجته خجله"}, {"t": "جعله يعم المملكه زين الاخبار", "s": "وطنيات", "u": "sections/wataniyat.html#p63", "x": "جعله يعم المملكه زين الاخبار | وتعيش ب أمن وازدهار وسرورا | للملكة شعب على داره يغار | ولاه للحكام ماهو يبورا"}, {"t": "يالله إني طالبك ياغفور ويارحوم", "s": "وطنيات", "u": "sections/wataniyat.html#p64", "x": "يالله إني طالبك ياغفور ويارحوم | عز دولتنا ووفق لنا حكامها | جعل من عادا بلدنا سريعات السهوم | جعل رب البيت يامر لها بإعدامها | من نوانا بالعداوه ياعله مايقوم | ودولته ياجعلها ماترز أعلامها"}, {"t": "ياناس شخص مايحب الحكومه", "s": "وطنيات", "u": "poems/065.html", "x": "ياناس شخص مايحب الحكومه | ضعيف دين وللمعاريف نكار | حنا بخير والبلاد محكومه | حكامها نخبه من خيار الاخيار | اللي يعاديها توقف علومه | لا جاه رجل ياصل العلم ب اخبار | من هاجسه ماعاد هو يزين نومه | يجني على نفسه بهرجه ويحتار"}, {"t": "اللي من بلدنا وانتزع في بلاد الغير", "s": "وطنيات", "u": "sections/wataniyat.html#p66", "x": "اللي من بلدنا وانتزع في بلاد الغير | وعود يسب بلادنا ناقص عرفه | هذا حسب عرفي بالصراحه وبالتفسير | وترى اللي يسب بلادنا شوفته قرفه"}, {"t": "الله يفك المملكه شر الاشرار", "s": "وطنيات", "u": "sections/wataniyat.html#p67", "x": "الله يفك المملكه شر الاشرار | من خان فيها جعل ربي يخونه"}, {"t": "اللي مايحب المملكه مايحب الدين", "s": "وطنيات", "u": "sections/wataniyat.html#p68", "x": "اللي مايحب المملكه مايحب الدين | واللي مايحب الدين ماحن بربع له"}, {"t": "راكب اللي لاركبته راح همي", "s": "قصائد الجيب", "u": "poems/069.html", "x": "راكب اللي لاركبته راح همي | مابغيته من طريقن مايكوده | لاركبته قال وين تريد عمي | مع صلاب القاع ولا مع نفوده | شركته من طبعها ماهي تذمي | ماخذه من ميزه الشركات جوده | والدي يابان والتيوته امي | كل منهم معطي الاخر عهوده | مايهم اللي مدح واللي يذمي | كل طيب لازم يثبت وجوده | جيب شاص لاعطى الدرب المهمي | يطرب اللي والده عنز جدوده"}, {"t": "أنا دامني باروح وأجي هواي الجيب", "s": "قصائد الجيب", "u": "poems/070.html", "x": "أنا دامني باروح وأجي هواي الجيب | لجل الجيب رغبة خاطري دامني بري | ترى مدحتي للجيب يالربع ماهو عيب | وقدني على لذة منافعه متضري | إذا سرت فوق الجيب تبرى لجل النيب | وناستك ونسة واحدن متهم وبري | ركوب المواتر كلها زين ماهو عيب | بس الجيب مثل اللي على المرجله ضري"}, {"t": "ترا ركبتي للجيب عند النياق علاج", "s": "قصائد الجيب", "u": "poems/071.html", "x": "ترا ركبتي للجيب عند النياق علاج | علاج الكبير ورغبته تبعت شفوفه | هواء العود لامنه صمل يبغي المنهاج | عوينه على المنهاج ماكثر ضروفه | قال ابشر بعزك للسفر وش حن بنحتاج | نجهزه من ذلحين والشد بنحوفه | ندق المواتر سلف قبل السفر ينباج | على حروت المنهاج للدرب مصفوفه"}, {"t": "الهاتف اللي ينقل اسماء المطاليق", "s": "قصائد المدح", "u": "poems/072.html", "x": "الهاتف اللي ينقل اسماء المطاليق | غالي علي لو كان ماهوب غالي | هواتف اللي عندي ألهم مواثيق | غلا معي من ماضيات الليالي | كلام صدق ماهو بزود تلفيق | ربع(ن) علي غالين والعود غالي | عود نحبه عاد حنا ملاحيق | وحبه تمكن يوم قد حن رجالي | لا جيت باوصف سجاياه ماطيق | طيبه على كل المجالات عالي | صقار طير وفي مجال التفافيق | رماي شوف العين ماهو يقالي | صدره على شغل الخوي ماهو يضيق | شغل الخوي عنده على طول حالي | كريم من عاد الذبايح تشافيق | عاد العرب مايملكون الريالي | ودليلة لادْلوّس الليل مايضيق | يدل دربه في السهل والجبالي | لطيف يرحم من ضعوف المخاليق | اللي عليه نقوص ولا يسالي | وشاعر وله في بصمه الشعر توثيق | ماينطق الا بالبيوت الجزالي | عطاه من رب المخاليق توفيق | سمح الجناب ومدهل(ن) للرجالي | هذا ابن مرعي مايبي زود تحقيق | هذا كلام الصدق ياللي تسالي | عز الله ان حنا لجيه مشافيق | حن بالجنوب وهو بدار الشمالي"}, {"t": "ذا الليل أمن ابرك ليالي ذا السنه والشهور", "s": "قصائد المدح", "u": "poems/073.html", "x": "ذا الليل أمن ابرك ليالي ذا السنه والشهور | وااستبشر بشوفكم ياطيبين المقام | والقلب متزايدن فيه الفرح والسرور | ويزيد فرحه اذا جاو الربوع الحشام | أنا احمد الله على دبرة مدبر لمور | اللي ومر بدر يسعف والده لين قام | أنا احمد الله وانا خاله ماهو بمعثور | رفيق دنيا من سلالة رجال كرام | طيبه لوالده يقنينا ويكسب الأجور | من عند ربه ويلقا من طرفنا احترام | ابوه قد طاح من شد المرض مايثور | كن العرب في نهار وهو يسير بظلام | من كثر ماجاه من لوجاع رجل صبور | يمزح مع الناس وان جاء النوم ماهو ينام | ماهو يبين على العربان بعض الأمور | ومن قو عزمه مابين للعرب لنهظام | ولا محمد مجرب عندنا ومخبور | اعلومه الطيبه عند الخلايق عظام | كم جاه محتاج كاربه الدهر ومعسور | قال ابشر بما يسرك صدق وأخذ الكلام | كم جاه متعطلن موتره عيا يدور | صلحه ابو ناصر وللطيب شد الحزام | مدة يمينه تخص الارمله والبزور | وقد لقبوه العرب من قبل يابو اليتام | وبيته معمر بضيفانه ماهوب مهجور | يجيه ضيفان من شرق الاراضي وشام | من جاه عين هلا والعود الازرق يدور | بشوش في وجه ضيفانه بحلو الكلام"}, {"t": "مرحبا بالي سؤاله في كلامه", "s": "قصائد المدح", "u": "poems/074.html", "x": "مرحبا بالي سؤاله في كلامه | منزلي مخليه لي ثالث اسبوعي | ملت النوقات من طول المقامه | والحيا طايح وانا فكري رموعي | خايف من قامه تلحق ملامه | والشوير الهزل ماني له بطوعي | يوم جاء حل الشديد وجاء مرامه | قالو الشبان خلوها تزوعي | حاسبين لسفر كل اهتمامه | والاجازه بالشهور وبالسبوعي | يوم كل الراي ولوني زمامه | قلت حنا راحلين ذا السبوعي | ياحمد ياويش لونك والسلامه | يالرفيق الذرب يالسيف القطوعي | يالرفيق اللي يواصلني سلامه | غالي عندي ومن ندر ربوعي | يابس راسه على عز وشهامه | وخذ وسام العرف من بين الجموعي | وكل ملاك الهجن تبغي إحترامه | لجل عرفه لاحكم مابه رجوعي"}, {"t": "مادامكم حيين ماباح سدي", "s": "قصائد عامه", "u": "poems/075.html", "x": "مادامكم حيين ماباح سدي | ولاضاق صدري في الليالي العسيرات | طيرن بلا جنحان ماهو يهدي | ولا يعدي في الطوال المنيفات | انا احمد الله يوم ماخاب كدي | ع الحرار اللي تعشق الجزيلات | حالي لحالك يالسنافي مفدي | ياراشد بيوتك حدتني بالأبيات | مادامني بكفيك يالقرم ودي | بالمال ولا بالتعب والكلوفات | الهرج لاهو يجيب ولا يودي | ولا بداوتنا بداوة دعايات | ولا نتبع اللي عن سنعنا يصدي | ومن راح معنا بشره بالمسرات"}, {"t": "دام رجلي تدعس البنص وعيوني تشوف", "s": "قصائد عامه", "u": "poems/076.html", "x": "دام رجلي تدعس البنص وعيوني تشوف | واتحمل للسـفر والديـار ادلـها | خلني أمشي دامني ماغدا عندي ظروف | في هواء النوقات مادامني هوي لها | مامضى من وقتي وراح ماهوب مخلوف | وأطمع الـدنيا وأفكر بـها وأمـلها | عشت مع نجع وراحوا يعشون الضيوف | ساترين لعرضهم فالمراجل كلها | لادعست ديارهم قمت اصفق بالكفوف | قلت حي اللي مضى والدموع اهلها"}, {"t": "سلام مني سلام", "s": "قصائد عامه", "u": "poems/077.html", "x": "سلام مني سلام | سلام واثني التحيه | تقديرللحاضرين | تحية للكرام | اهل الوفاوالحميه | لطامة العايلين | حماية للجهام | إلى لفاهم غزيه | يبغون كسب ثمين | يبغون برد و سلام | واللبل وراها سريه | تقصرخطا العايلين | لاصاح خاطي غلام | وثور له ابندقيه | في لأرض له طلقتين | وجاوه عيال همام | يردون حوض المنيه | لرواحهم جالبين | وين أنت يابن الكرام | عطنا علوم طريه | وعجل بها ياذهين | ثم قال مامن كلام | اللبل خذوها اللظيه | واقفوا بها الطامعين | ياهل الفعول القدام | عاداتكم لوليه | تروون حد السنين | لعيون راعي الوشام | اللي يحذف أغطيه | يقول ياالمستحين | حرام والله حرام | إنردحوض المنيه | ميرادة المعطشين | معاد فيها التزام | كل(ن) سلاحه خويه | يطلب من الله يعين | اللبل جلال العظام | لون إنها بالهنيه | قد كملت من سنين | من قبل وقت الكمام | من عاد بقعا صبيه | من دونها معتصين | واليوم فأمن ومنام | في ظل دوله قويه | تضرب يدالعابثين | وأختامها و السلم | على محمد نبيه | هو سيدالمرسلين"}, {"t": "بديت بالي عالمن كل الاحوال", "s": "قصائد عامه", "u": "poems/078.html", "x": "بديت بالي عالمن كل الاحوال | الي يعرف البينه والخفيه | رب رئوف كل عباده اتسال | انه يغفر ذنوبها والخطيه | من عقب ذكره باتمثل لي امثال | الله يوفقنا البيوت الطريه | في ليل قمراً فيه لنمبات واهلال | وضون تشب ودلتن شاذليه | يتعب عليها لاجل سمحين الاقبال | كل ابلجن ماهو يخون بخويه | يتعب على العليا ولاو يخسر المال | ومعا المراجل عندهم حسن نيه | الطيب سندا والردا راس هيال | كلن يعرف العاليه والدنيه | من لا تعب على الصعيبات مانال | قول ونعم عند الرجال الوفيه | وابذكر الله عد ماهل همال | وعلى النبي مني صلاة وتحيه"}, {"t": "عيني اللي بالمطاليق مسروره", "s": "قصائد عامه", "u": "poems/079.html", "x": "عيني اللي بالمطاليق مسروره | وجسمي اللي كافي النوم مانامه | شفت دمع العين في الخد منثوره | يوم شاف الرجل لابته واحزامه | يعجز الرجال مايملك شعوره | يوم صفو كلهم عند دهامه | يمسكون صفوف بالصوت والصوره | الشبل والي يتشكى من اعظامه | عرضنا بوجودهم زايد نوره | شوف ربعي عندي الفوز ووسامه | شاقني شوف النشاما وجمهوره | بين جمعا لمت الناس واعلامه | ماهي بمن غايب الربع مقصوره | كل منهم يرفع الراس كلامه | منهم الي جا وشاركني بشوره | ومنهم الي جا وطوف على زامه"}];